import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxCard,
  JxDivider,
  JxSegmented,
  JxSelect,
  JxSlider,
  JxSwitch,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...DEFAULTS,
    ...defaultValue,
  });

  const update = useCallback(
    <K extends keyof AppearanceSettings>(key: K, value: AppearanceSettings[K]) => {
      setSettings((prev) => {
        const next = { ...prev, [key]: value };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === settings.theme)?.label ?? '';

  return (
    <JxCard
      className="jx-stack"
      style={{ gap: 'var(--jx-space-6)', padding: 'var(--jx-space-6)' }}
    >
      <header
        className="jx-row"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 className="jx-heading" style={{ margin: 0 }}>
          Внешний вид
        </h2>
        <JxBadge variant="neutral">{themeLabel}</JxBadge>
      </header>

      <section className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <label className="jx-label" id="appearance-theme-label">
          Тема
        </label>
        <JxSegmented
          aria-labelledby="appearance-theme-label"
          options={THEME_OPTIONS}
          value={settings.theme}
          onValueChange={(value: ThemeMode) => update('theme', value)}
        />
      </section>

      <section className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 'var(--jx-space-3)',
          }}
        >
          <label className="jx-label" id="appearance-scale-label">
            Масштаб интерфейса
          </label>
          <span className="jx-text-muted">{settings.scale}%</span>
        </div>
        <JxSlider
          aria-labelledby="appearance-scale-label"
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value: number) => update('scale', value)}
        />
      </section>

      <section
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-4)',
        }}
      >
        <label className="jx-label" htmlFor="appearance-dense">
          Плотная вёрстка
        </label>
        <JxSwitch
          id="appearance-dense"
          checked={settings.dense}
          onCheckedChange={(checked: boolean) => update('dense', checked)}
        />
      </section>

      <JxDivider />

      <section className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
        <h3 className="jx-heading" style={{ margin: 0 }}>
          Ещё
        </h3>
        <div className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" id="appearance-font-label">
            Шрифт
          </label>
          <JxSelect
            aria-labelledby="appearance-font-label"
            options={FONT_OPTIONS}
            value={settings.fontFamily}
            onValueChange={(value: string) => update('fontFamily', value)}
          />
        </div>
      </section>
    </JxCard>
  );
}

export default AppearanceSettingsScreen;

